export function addItem(items, item) {
  return [...items, { ...item }];
}

export function editPrice(items, id, price) {
  return items.map(item => item.id === id ? { ...item, price } : item);
}

export function removeItem(items, id) {
  return items.filter(item => item.id !== id);
}

